import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider} from '../types/ai.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const failingProvider = (reason: unknown): AIProvider => ({
  sendMessage: () => ({
    [Symbol.asyncIterator]: () => ({next: () => Promise.reject(reason)}),
  }),
  generateStructured: () => Promise.resolve({} as never),
});

const causesSeen = async (reason: unknown): Promise<unknown[]> => {
  const causes: unknown[] = [];
  const orchestrator = createChatOrchestrator(
    failingProvider(reason),
    new PromptBuilder({identity: 'You are a test assistant.'}),
    undefined,
    {
      hooks: {
        onError: async (_session, error) => {
          causes.push(error.cause);
        },
      },
    }
  );
  const session = {
    sessionId: 's',
    userId: 'u',
    entries: [{role: 'user' as const, content: 'hi', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  await orchestrator.processMessage(session).catch(() => undefined);
  return causes;
};

describe('ChatOrchestrator onError cause for non-Error rejections', () => {
  it.each([
    ['a string', 'string boom'],
    ['a plain object', {code: 503}],
    ['undefined', undefined],
  ])('keeps %s as the cause of the Error passed to onError', async (_label, reason) => {
    expect(await causesSeen(reason)).toEqual([reason]);
  });
});
